package app.kinexo;
import android.app.*; import androidx.media3.exoplayer.ExoPlayer; import androidx.media3.common.MediaItem; import androidx.media3.common.Player; import androidx.media3.common.PlaybackException; import androidx.media3.ui.PlayerView; import android.graphics.Typeface; import android.graphics.drawable.GradientDrawable; import android.content.res.ColorStateList; import android.view.inputmethod.InputMethodManager; import android.os.*; import android.graphics.Color; import android.view.*; import android.widget.*; import android.net.Uri; import org.json.*; import java.net.*; import java.io.*;
public class MainActivity extends Activity {
 String endpoint=""; String lastQuery=""; LinearLayout root,results; EditText query; ExoPlayer video; Runnable failover; int generation=0;
 int dp(int n){return (int)(n*getResources().getDisplayMetrics().density);}
 TextView label(String s,int size){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(Color.rgb(25,30,40));t.setPadding(0,dp(10),0,dp(10));return t;}
 public void onCreate(Bundle b){super.onCreate(b);endpoint=BuildConfig.SEARCH_API.trim().replaceAll("/+$","");home();}
 GradientDrawable round(int color,int radius){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(radius));return d;}
 void style(Button b,boolean primary){b.setAllCaps(false);b.setTextColor(primary?Color.WHITE:Color.rgb(25,30,40));b.setBackground(round(primary?Color.rgb(37,48,75):Color.WHITE,14));b.setPadding(dp(16),dp(12),dp(16),dp(12));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,dp(8),0,dp(4));b.setLayoutParams(p);}
 void home(){generation++; failover=null; video=null; root=new LinearLayout(this);root.setOrientation(1);root.setPadding(dp(24),dp(32),dp(24),dp(16));root.setBackgroundColor(Color.rgb(247,248,251));setContentView(root);root.setOnApplyWindowInsetsListener((v,i)->{v.setPadding(dp(24),dp(20)+i.getSystemWindowInsetTop(),dp(24),dp(16)+i.getSystemWindowInsetBottom());return i;});TextView brand=label("KINEXO",36);brand.setTypeface(Typeface.DEFAULT,Typeface.BOLD);root.addView(brand);root.addView(label("Найди. Нажми. Смотри.",16));query=new EditText(this);query.setSingleLine(true);query.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(150)});query.setText(lastQuery);query.setHint("Название фильма");query.setImeOptions(3);query.setBackground(round(Color.WHITE,16));query.setPadding(dp(16),dp(14),dp(16),dp(14));root.addView(query);Button b=new Button(this);b.setText("Найти");style(b,true);root.addView(b);b.setOnClickListener(v->search());query.setOnEditorActionListener((v,a,e)->{search();return true;});ScrollView sc=new ScrollView(this);results=new LinearLayout(this);results.setOrientation(1);sc.addView(results);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));results.addView(label("Введите название фильма или сериала.",15));}
 JSONObject get(String url)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL(url).openConnection();c.setRequestProperty("Accept","application/json");c.setConnectTimeout(10000);c.setReadTimeout(25000);try(InputStream in=c.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] buf=new byte[8192];int n;while((n=in.read(buf))!=-1){out.write(buf,0,n);if(out.size()>8000000)throw new IOException("Response too large");}return new JSONObject(out.toString("UTF-8"));}finally{c.disconnect();}}
 String enc(String s)throws Exception{return URLEncoder.encode(s,"UTF-8");}
 void search(){String q=query.getText().toString().trim();if(q.length()<2){query.setError("Введите минимум 2 символа");return;}if(q.length()>150){query.setError("Максимум 150 символов");return;}query.setError(null);lastQuery=q;((InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(query.getWindowToken(),0);if(!endpoint.isEmpty()){serverSearch(q);return;}archiveSearch(q);}
 void archiveSearch(String q){int token=++generation;results.removeAllViews();results.addView(label("Поиск…",16));new Thread(()->{try{String safe=q.replaceAll("[^\\p{L}\\p{N} ]"," ");JSONObject j=get("https://archive.org/advancedsearch.php?q="+enc("title:("+safe+") AND mediatype:movies AND licenseurl:*creativecommons.org*")+"&fl[]=identifier&fl[]=title&rows=25&output=json");JSONArray a=j.getJSONObject("response").getJSONArray("docs");runOnUiThread(()->{if(token!=generation)return;results.removeAllViews();if(a.length()==0)results.addView(label("Ничего не найдено",18));for(int i=0;i<a.length();i++){JSONObject m=a.optJSONObject(i);if(m==null)continue;String id=m.optString("identifier"),title=m.optString("title",id);Button row=new Button(this);row.setAllCaps(false);row.setText("▶  "+title);style(row,false);results.addView(row);row.setOnClickListener(v->resolve(id,title));}});}catch(Exception e){runOnUiThread(()->{if(token==generation){results.removeAllViews();results.addView(label("Ошибка сети. Повторите поиск.",16));}});}}).start();}

 void serverSearch(String q){int token=++generation;String base=endpoint;results.removeAllViews();results.addView(label("Поиск по источникам…",16));new Thread(()->{try{JSONObject data=get(base+"/search?q="+enc(q));JSONArray items=data.getJSONArray("results");runOnUiThread(()->{if(token!=generation)return;results.removeAllViews();JSONArray failed=data.optJSONArray("unavailable_providers");if(items.length()==0&&failed!=null&&failed.length()>0){archiveSearch(q);return;}if(items.length()==0)results.addView(label("Ничего не найдено",18));if(failed!=null&&failed.length()>0)results.addView(label("Часть источников недоступна",14));for(int i=0;i<items.length();i++){JSONObject item=items.optJSONObject(i);if(item==null)continue;Button row=new Button(this);row.setAllCaps(false);row.setText("▶  "+item.optString("title"));style(row,false);results.addView(row);row.setOnClickListener(v->{java.util.ArrayList<String> urls=new java.util.ArrayList<>();addUrl(urls,item.optString("url"));JSONArray alt=item.optJSONArray("alternatives");if(alt!=null)for(int k=0;k<alt.length();k++){JSONObject a=alt.optJSONObject(k);if(a!=null)addUrl(urls,a.optString("url"));}if(!urls.isEmpty())playAlternatives(item.optString("title"),urls,0);else Toast.makeText(this,"Нет доступного видео",Toast.LENGTH_SHORT).show();});}});}catch(Exception e){runOnUiThread(()->{if(token==generation){archiveSearch(q);}});}}).start();}
 void addUrl(java.util.ArrayList<String> urls,String u){if("https".equals(Uri.parse(u).getScheme())&&!urls.contains(u))urls.add(u);}
 void playAlternatives(String title,java.util.ArrayList<String> urls,int index){play(title,urls.get(index));failover=()->{if(index+1<urls.size()){video.release();playAlternatives(title,urls,index+1);}else Toast.makeText(this,"Все источники недоступны",Toast.LENGTH_LONG).show();};}
 void resolve(String id,String title){int token=++generation;results.removeAllViews();results.addView(label("Подготовка видео…",16));new Thread(()->{try{JSONObject j=get("https://archive.org/metadata/"+enc(id));JSONArray a=j.getJSONArray("files");String path=null;for(int i=0;i<a.length();i++){String n=a.getJSONObject(i).optString("name");if(n.toLowerCase(java.util.Locale.ROOT).endsWith(".mp4")){path=n;break;}}if(path==null)throw new IOException();String url="https://archive.org/download/"+Uri.encode(id)+"/"+Uri.encode(path,"/");runOnUiThread(()->{if(token==generation)play(title,url);});}catch(Exception e){runOnUiThread(()->{if(token==generation){results.removeAllViews();results.addView(label("Видео недоступно. Повторите поиск.",16));}});}}).start();}
 void play(String title,String url){generation++;failover=null;root.removeAllViews();Button back=new Button(this);back.setText("Назад к поиску");style(back,false);root.addView(back);back.setOnClickListener(v->{video.release();home();if(!lastQuery.isEmpty())search();});root.addView(label(title,22));PlayerView playerView=new PlayerView(this);root.addView(playerView,new LinearLayout.LayoutParams(-1,0,1));video=new ExoPlayer.Builder(this).build();playerView.setPlayer(video);playerView.setShowBuffering(PlayerView.SHOW_BUFFERING_WHEN_PLAYING);video.addListener(new Player.Listener(){@Override public void onPlayerError(PlaybackException error){if(failover!=null){Runnable next=failover;failover=null;next.run();}else Toast.makeText(MainActivity.this,"Не удалось воспроизвести видео",Toast.LENGTH_LONG).show();}});video.setMediaItem(MediaItem.fromUri(url));video.prepare();video.play();}
 @Override public void onBackPressed(){if(video!=null){video.release();home();if(!lastQuery.isEmpty())search();}else super.onBackPressed();}
 @Override protected void onDestroy(){generation++;if(video!=null)video.release();super.onDestroy();}
 @Override protected void onStop(){super.onStop();if(video!=null)video.pause();}
}
